from ta5g_admin_operations import ta_admin_interface
from robot.api import logger
import pprint
import re


class Measurements(object):
    UE_MEAS_CONFIG_DISP_REGEXP = re.compile(r'=== UE\d+ MEASUREMENT IDENTITIES:.*-+.*=+', re.DOTALL)

    def __repr__(self):
        return "meas_obj: {}\nreport_conf: {}\nmeas_id: {}".format(
            pprint.pformat(self.meas_obj_dict),
            pprint.pformat(self.report_conf_dict),
            pprint.pformat(self.meas_id_dict),
        )

    def _get_measurement_data_from_egate(self, ue, wtssim_lib, timeout=5, terminal_width=200):
        meas_cfg_str = wtssim_lib.execute_egate_command_and_wait_for_data(
            cmd='ue_meas_cfg_disp id={}'.format(ue), timeout=timeout, pass_regexp=self.UE_MEAS_CONFIG_DISP_REGEXP
        )
        meas_cfg_str = self._remove_escape_sequences(meas_cfg_str)
        logger.trace(repr(meas_cfg_str))
        lines = [line.strip() for line in meas_cfg_str.splitlines() if len(line.strip()) != 0]
        return '\r\n'.join(self._join_long_lines(lines, terminal_width))

    def _remove_escape_sequences(self, input):
        """
        Ensures that no escape sequences are present in input
        :param input:
        :return:
        """
        return input.replace('\x1b[K', '')

    def _join_long_lines(self, lines, terminal_width):
        """
        Ensures that lines broken due to virtual terminal width are joined back together
        :param lines:
        :return:
        """
        i = 0
        while i < len(lines) - 1:
            if len(lines[i]) % terminal_width == 0:
                lines[i] += lines[i + 1]
                del lines[i + 1]
            else:
                i += 1
        logger.debug(pprint.pformat(lines))
        return lines

    def __init__(self, ue, wtssim_lib):
        self.nlines = self._get_measurement_data_from_egate(ue, wtssim_lib)
        self._build_measurement_dict(ue)
        logger.info(
            "Measurement objects:\n{}\n\nReport configurations:\n{}\n\nMeasurement identities:\n\n{}".format(
                pprint.pformat(self.meas_obj_dict),
                pprint.pformat(self.report_conf_dict),
                pprint.pformat(self.meas_id_dict),
            )
        )

    def _build_data_table(self, text_table):
        """
        Creates python list from text table
        :param text_table:
        :return:
        """
        result = []
        for line in text_table:
            row = []
            for x in line.split():
                try:
                    row.append(int(x.strip()))
                except Exception:
                    row.append(x.strip())
            result.append(row)
        return result

    def _build_measurement_dict(self, ue):
        """
        Metho parses egate output and converts it to python lists and then dictionaries.
        Regular expressions used match entire tables containing data, eg.:
        Regexp 'UE1 MEASUREMENT OBJECTS:.*?-+?(.*?)=+?'
        means                          \\ /\\/\\  /\\/
                                         1  2   3   4
        1 - any number of any character (non-greedy) - text including = signs, column names
        2 - '-' character one or more times (non-greedy) - row of '-' which is beginning of records
        3 - capture any character any number of times (non-greedy) - data table rows
        4 - '=' character one or more times (non-greedy) - row of '=' which is end of the table
        and matches eg.:
        "
        === UE1 MEASUREMENT OBJECTS:
        =====================================
        Id RAT CarrierFreq offsetFreq
        -------------------------------------
        1 EUTRAN 2000 -
        2 EUTRAN 2525 -
        3 EUTRAN 3600 -
        4 EUTRAN 2700 -
        5 EUTRAN 3000 -
        6 EUTRAN 300 -
        7 EUTRAN 1500 -
        =====================================
        "
        :param ue:
        :return:
        """
        try:
            text_table = (
                re.search(r'UE{} MEASUREMENT OBJECTS:.*?-+?(.*?)=+?'.format(ue), self.nlines, re.DOTALL)
                .groups()[0]
                .replace('-', '')
                .strip()
                .splitlines()
            )
            self.meas_obj = self._build_data_table(text_table)
            text_table = (
                re.search(r'UE{} NR REPORT CONFIGURATIONS.*?-+?(.*?)=+?'.format(ue), self.nlines, re.DOTALL)
                .groups()[0]
                .replace('-', '')
                .strip()
                .splitlines()
            )
            self.report_conf = self._build_data_table(text_table)
            text_table = (
                re.search(r'UE{} NR MEASUREMENT IDENTITIES.*?-+?(.*?)=+?'.format(ue), self.nlines, re.DOTALL)
                .groups()[0]
                .replace('-', '')
                .strip()
                .splitlines()
            )

            self.meas_id = self._build_data_table(text_table)
            self.meas_obj_dict = {}
            for meas_obj in self.meas_obj:
                self.meas_obj_dict[meas_obj[0]] = {'ran': meas_obj[1], 'carrier_freq': meas_obj[2]}

            self.report_conf_dict = {}
            trigger_events_for_report_configuration = re.search(
                r'DETAILED INFO ABOUT NR REPORT CONFIGURATIONS:\r\n(.*?)EGATE', self.nlines, re.DOTALL).groups()[0]
            for report_conf in self.report_conf:
                self.report_conf_dict[report_conf[0]] = {
                    'ran': report_conf[1],
                    'type': report_conf[2],
                    'trigger': report_conf[3],
                    'report_quantity': report_conf[4],
                    'max_report_cells': report_conf[5],
                    'report_interval': report_conf[6],
                    'report_amount': report_conf[7],
                }
                details = re.search(
                    r'UE{} TRIGGER EVENT for report configuration {}:\r\n(.*?)\r\n'.format(ue, report_conf[0]),
                    trigger_events_for_report_configuration,
                    re.DOTALL,
                ).groups()[0]
                self.report_conf_dict[report_conf[0]].update(self._parse_report_conf_details(details))

            self.meas_id_dict = {}
            for meas_id in self.meas_id:
                self.meas_id_dict[meas_id[0]] = {'meas_obj_id': meas_id[1], 'report_config_id': meas_id[2]}
        except AttributeError:
            logger.info("Measurement Configuration for the UE is not available", also_console=True)

    def _parse_report_conf_details(self, details):
        """
        Parsed DETAILED INFO ABOUT REPORT CONFIGURATION section.
        Event parameters are inconsistent and differ from event to event, eg.:
        EventA3: (a3_Offset=4 reportOnLeave=false)
        EventA5: 1:Threshold: RSRP 45 2:Threshold: RSRP 48
        EventA2: Threshold: RSRP 30
        EventB2: EUTRA: Threshold: RSRQ 7 GERAN: threshold=20
        :param details:
        :return:
        """
        details = re.sub(", UTRA:", " UTRA:", details)
        records = re.split(r', ', re.sub('[()]', '', details))
        details_dict = dict(record.split(': ', 1) for record in records)
        for key, value in list(details_dict.items()):
            if 'Event' in key:
                if ':' in value:
                    event_params = re.findall(
                        r'((?:threshold\d+=)?Threshold:.*?\d+|EUTRA:.*?\d+|GERAN:.*?\d+|UTRA:.*?\d+)[ ]?', value, re.DOTALL
                    )
                    param_dict = dict(param.split(': ', 1) for param in event_params)
                else:
                    event_params = value.split(' ')
                    event_params = [event for event in event_params if '=' in event]
                    param_dict = dict(param.split('=') for param in event_params)
                details_dict[key] = param_dict
        return details_dict

    def find_active_report_ids_on_frequency(self, carrier_freq, event_type='Event'):
        """
        Method returns report configuration ids that are active on given frequency that have specified event_type.
        :param carrier_freq:
        :param event_type: Checks if given value is contained within report event type, eg.:
        default value 'Event' matches every event
        'EventA' matches events A1, A2, A3 etc.
        'EventA3' or simply 'A3' will match only report configuration with event type EventA3
        :return:
        """
        carrier_freq = int(carrier_freq)
        meas_obj_id = -1
        for id, meas_obj in list(self.meas_obj_dict.items()):
            if meas_obj['carrier_freq'] == carrier_freq:
                meas_obj_id = id
                break
        report_ids = []
        for id, meas_id in list(self.meas_id_dict.items()):
            if (
                meas_id['meas_obj_id'] == meas_obj_id
                and event_type in self.report_conf_dict[meas_id['report_config_id']]['type']
            ):
                report_ids.append(meas_id['report_config_id'])
        return report_ids

    def get_events_active_on_frequency(self, carrier_freq):
        """
        Method returns measurement events active on given frequency. Events can repeat.
        :param carrier_freq:
        :return:
        """
        carrier_freq = int(carrier_freq)
        reports = self.find_active_report_ids_on_frequency(carrier_freq)
        return [self.report_conf_dict[id]['type'] for id in reports]

    def get_frequencies_order(self):
        """
        Method returns frequencies order in measurement configuration.
        Frequencies are not repeated: if different events are active on same frequency first occurrence is counted
        :return:
        """
        meas_obj_ids = []
        for meas_id in list(self.meas_id_dict.values()):
            if meas_id['meas_obj_id'] not in meas_obj_ids:
                meas_obj_ids.append(meas_id['meas_obj_id'])
        return [self.meas_obj_dict[id]['carrier_freq'] for id in meas_obj_ids]

    def get_meas_id_for_measurement_on_frequency(self, meas_type, carrier_freq, trigger):
        """
        Returns measurement id of given measuerment type on given frequency
        :param meas_conf:
        :param meas_type:
        :param carrier_freq:
        :return:
        """
        carrier_freq = int(carrier_freq)
        for id, meas_id in list(self.meas_id_dict.items()):
            if (
                self.meas_obj_dict[meas_id['meas_obj_id']]['carrier_freq'] == carrier_freq
                and self.report_conf_dict[meas_id['report_config_id']]['type'] == meas_type
                and self.report_conf_dict[meas_id['report_config_id']]['trigger'] == trigger
            ):
                return id
        raise Exception(
            "No matching measurement id was found for "
            "type {}, carrier frequency {} and trigger {} in configuration {}".format(
                repr(meas_type), repr(carrier_freq), repr(trigger), repr(self)
            )
        )

    def get_meas_trigger_value(self, cell_id='1', moc='NRCELL_A', event_structure='a1MeasSCellAddSsbRsrp',
                               parameter='a1ThresholdPCellSwitchSsbRsrp'):
        object_name = moc + '-' + cell_id
        with ta_admin_interface.admin_interface() as admin_client:
            infomodel_object = admin_client.get_managed_objects(moc)
            for item in infomodel_object:
                if object_name in item['distName']:
                    object_name_data = item
                    logger.info('Parameter {} value of cell {} is {}'.
                                format(parameter, cell_id, str(object_name_data['parameters'][event_structure][parameter])),
                                also_console=True)
                    return str(object_name_data['parameters'][event_structure][parameter])

    def get_arfcnSsbPbch_value(self, parameter_name='arfcnSsbPbch', moc='NRCELL_R', cell_id='1'):
        object_name = moc + '-' + cell_id
        with ta_admin_interface.admin_interface() as admin_client:
            infomodel_object = admin_client.get_managed_objects(moc)
            for element in infomodel_object:
                if object_name in element['distName']:
                    logger.info('arfcnSsbPbch value of cell {} is equal {} '.
                                format(cell_id, element['parameters'][parameter_name]), also_console=True)
                    return str(element['parameters'][parameter_name])

    def get_meas_id_for_A1_scell_addition(self, trigger_type='RSRP', pcell_id='1', scellTechnology='FDD'):
        meas_type = 'EventA1'
        carrier_freq = int(self.get_arfcnSsbPbch_value(cell_id=pcell_id))
        if trigger_type == 'RSRP':
            if scellTechnology == 'TDD':
                a1ThresholdSCellAdd_value = self.get_meas_trigger_value(cell_id=pcell_id,
                                                                        event_structure='a1MeasSCellAddSsbRsrp',
                                                                        parameter='a1ThresholdSCellAddSsbRsrpTDD')
            else:
                a1ThresholdSCellAdd_value = self.get_meas_trigger_value(cell_id=pcell_id,
                                                                        event_structure='a1MeasSCellAddSsbRsrp',
                                                                        parameter='a1ThresholdSCellAddSsbRsrpFDD')
        else:
            a1ThresholdSCellAdd_value = self.get_meas_trigger_value(cell_id=pcell_id, event_structure='a1MeasSCellAddSsbRsrq',
                                                                    parameter='a1ThresholdSCellAddSsbRsrq')
        for id, meas_id in list(self.meas_id_dict.items()):
            if (
                self.meas_obj_dict[meas_id['meas_obj_id']]['carrier_freq'] == carrier_freq
                and self.report_conf_dict[meas_id['report_config_id']]['type'] == meas_type
                and self.report_conf_dict[meas_id['report_config_id']][meas_type]['Threshold'] == trigger_type + " " + str(a1ThresholdSCellAdd_value)
            ):
                logger.info('Meas ID for A1 SCell Addition, {} trigger type, carrier frequency {} and threshold value {} is {}'
                            .format(trigger_type, carrier_freq, a1ThresholdSCellAdd_value, id), also_console=True)
                return id
        raise Exception(
            "No matching measurement id was found for "
            "type {}, carrier frequency {} and trigger {} in configuration {}".format(
                repr(meas_type), repr(carrier_freq), repr(trigger_type), repr(self)
            )
        )

